#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0 || n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long catalan[31];
    catalan[0] = 1ULL;
    for (int i = 1; i <= n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += catalan[j] * catalan[i - 1 - j];
        }
        catalan[i] = sum;
    }
    printf("%llu\n", catalan[n]);
    return 0;
}
}
